import json,glob,collections
c=collections.Counter()
for f in sorted(glob.glob('data/*.jsonl')):
  for l in open(f):
    r=json.loads(l); c[(f[-8:-6],r['stream'],r['schema_version'])]+=1
for k,v in sorted(c.items()): print(k,v)
"

